#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t n = strlen(s1);
    size_t m = strlen(s2);
    if (n > 64 || m > 64) {
        puts("TOO_LONG");
        return 0;
    }
    int dp[65][65];
    for (size_t i = 0; i <= n; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= m; ++j) dp[0][j] = (int)j;
    for (size_t i = 1; i <= n; ++i) {
        for (size_t j = 1; j <= m; ++j) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                int del = dp[i-1][j] + 1;
                int ins = dp[i][j-1] + 1;
                int sub = dp[i-1][j-1] + 1;
                int mn = del < ins ? del : ins;
                dp[i][j] = mn < sub ? mn : sub;
            }
        }
    }
    printf("%d\n", dp[n][m]);
    return 0;
}
